// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.owner();
        vm.prank(owner);
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok ? address(c).balance == 0 : true);
    }
}
